#!/usr/bin/env python3
"""
Script to copy generated files to submission folder
Run this after cifar10_evaluation.py completes
"""

import os
import shutil
from pathlib import Path

def copy_to_submission():
    """Copy all required files to submission folder"""
    
    # Define paths
    base_dir = Path("c:/Users/Admin/D802 STN1 Task 4 Evaluation of the Network Architecture Model")
    submission_dir = base_dir / "submission"
    
    # Files to copy (generated by main script)
    files_to_copy = [
        "final_report.md",
        "training_curves.png", 
        "confusion_matrix.png",
        "misclassified_examples.png"
    ]
    
    print("🔄 Copying generated files to submission folder...")
    print(f"📁 Submission folder: {submission_dir}")
    
    copied_files = []
    missing_files = []
    
    for filename in files_to_copy:
        source_path = base_dir / filename
        dest_path = submission_dir / filename
        
        if source_path.exists():
            try:
                shutil.copy2(source_path, dest_path)
                copied_files.append(filename)
                print(f"✅ Copied: {filename}")
            except Exception as e:
                print(f"❌ Error copying {filename}: {e}")
        else:
            missing_files.append(filename)
            print(f"⚠️  Missing: {filename}")
    
    print(f"\n📊 Summary:")
    print(f"✅ Successfully copied: {len(copied_files)} files")
    print(f"⚠️  Missing files: {len(missing_files)} files")
    
    if copied_files:
        print(f"\n✅ Copied files:")
        for file in copied_files:
            print(f"   - {file}")
    
    if missing_files:
        print(f"\n⚠️  Still waiting for:")
        for file in missing_files:
            print(f"   - {file}")
        print(f"\n💡 These files will be generated when cifar10_evaluation.py completes")
    
    # Check current submission folder contents
    print(f"\n📁 Current submission folder contents:")
    if submission_dir.exists():
        for file in sorted(submission_dir.iterdir()):
            if file.is_file():
                print(f"   ✅ {file.name}")
    
    print(f"\n📸 Don't forget to:")
    print(f"   1. Take screenshot of final training epoch")
    print(f"   2. Save screenshot as 'final_epoch_screenshot.png' in submission folder")
    print(f"   3. Verify all 8 files are ready for submission")

if __name__ == "__main__":
    copy_to_submission()